import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p16_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matmul_transposed_a(torch::Tensor A, torch::Tensor B);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_transposed_a", &matmul_transposed_a, "C = A^T * B via cuBLAS");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <ATen/cuda/CUDAContext.h>

// Compute C = A^T * B
// A: [K, M] (stored row-major), B: [K, N] (stored row-major)
// C: [M, N] (stored row-major)
//
// cuBLAS is column-major. We use the identity:
//   C_row = A^T_row * B_row
// In column-major terms, treating row-major [K,M] as col-major [M,K]:
//   C_col[M,N] = (A_col[M,K])^T_col * B_col[N,K]^T
// Equivalently, compute C^T = B^T * A in column-major:
//   cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N, M, N, K, ...)
// with A as the first operand (transposed) and B as second.
//
// Row-major A[K,M]: lda = M (leading dim in col-major = number of rows = M... wait)
// Let's be precise:
//   A is row-major [K, M]: pointer a, stride between rows = M
//     In col-major view: A is [M, K] with lda = M
//   B is row-major [K, N]: pointer b, stride between rows = N
//     In col-major view: B is [N, K] with ldb = N
//   C is row-major [M, N]: pointer c, stride between rows = N
//     In col-major view: C is [N, M] with ldc = N
//
// We want C_row[M,N] = A_row^T[M,K] * B_row[K,N]
// In col-major: C_col[N,M] = B_col[N,K] * A_col[M,K]^T
// So: cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_T, N, M, K,
//                alpha, b, ldb=N, a, lda=M, beta, c, ldc=N)

torch::Tensor matmul_transposed_a(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Tensors must be on CUDA");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Tensors must be float32");
    A = A.contiguous();
    B = B.contiguous();

    // A: [K, M], B: [K, N], C: [M, N]
    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(1);
    TORCH_CHECK(B.size(0) == K, "Dimension mismatch: A is [K,M] and B must be [K,N]");

    auto C = torch::empty({M, N}, A.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();

    float alpha = 1.0f;
    float beta = 0.0f;

    // col-major: C[N,M] = B[N,K] * A[M,K]^T
    // cublasSgemm(handle, transa, transb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc)
    // m=N, n=M, k=K
    // A_cublas = B (col-major [N,K]), lda=N, op=CUBLAS_OP_N
    // B_cublas = A (col-major [M,K]), ldb=M, op=CUBLAS_OP_T
    // C_cublas = C (col-major [N,M]), ldc=N
    cublasSgemm(handle,
                CUBLAS_OP_N, CUBLAS_OP_T,
                N, M, K,
                &alpha,
                B.data_ptr<float>(), N,
                A.data_ptr<float>(), M,
                &beta,
                C.data_ptr<float>(), N);

    return C;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a single matrix multiplication (C = A * B)
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs matrix multiplication.

                Args:
                    A: Input tensor of shape (M, K).
                    B: Input tensor of shape (K, N).

                Returns:
                    Output tensor of shape (M, N).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        A = A.contiguous()
        B = B.contiguous()
        return _stark_get_extension().matmul_transposed_a(A, B)
        # <<<END_IMPROVE>>>

