#include <mutex>

// Cached cublasLt state for the fixed shapes
struct CublasLtState {
    cublasLtHandle_t handle = nullptr;
    void* workspace = nullptr;
    size_t workspace_size = 32 * 1024 * 1024; // 32MB workspace
    bool initialized = false;
    std::mutex mtx;
};

static CublasLtState g_lt_state;

static void ensure_lt_initialized() {
    if (g_lt_state.initialized) return;
    std::lock_guard<std::mutex> lock(g_lt_state.mtx);
    if (g_lt_state.initialized) return;
    cublasLtCreate(&g_lt_state.handle);
    cudaMalloc(&g_lt_state.workspace, g_lt_state.workspace_size);
    g_lt_state.initialized = true;
}

// Compute C = A^T * B
// A: [K, M] row-major, B: [K, N] row-major, C: [M, N] row-major
// cuBLAS col-major mapping:
//   A col-major [M, K] with lda=M
//   B col-major [N, K] with ldb=N
//   C col-major [N, M] with ldc=N
// C_col[N,M] = B_col[N,K] * A_col[M,K]^T
// => cublasLtMatmul with transa=CUBLAS_OP_N, transb=CUBLAS_OP_T, m=N, n=M, k=K

