    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Tensors must be on CUDA");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Tensors must be float32");
    A = A.contiguous();
    B = B.contiguous();

    int K = (int)A.size(0);
    int M = (int)A.size(1);
    int N = (int)B.size(1);
    TORCH_CHECK((int)B.size(0) == K, "Dimension mismatch");

    auto C = torch::empty({M, N}, A.options());

    ensure_lt_initialized();

    float alpha = 1.0f, beta = 0.0f;

    // Create matmul descriptor with TF32 compute
    cublasLtMatmulDesc_t matmul_desc;
    cublasLtMatmulDescCreate(&matmul_desc, CUBLAS_COMPUTE_32F_FAST_TF32, CUDA_R_32F);

    // We compute: C_col[N,M] = B_col[N,K] * A_col[M,K]^T
    // transa = CUBLAS_OP_N (B is not transposed in col-major)
    // transb = CUBLAS_OP_T (A is transposed in col-major)
    cublasOperation_t transa = CUBLAS_OP_N;
    cublasOperation_t transb = CUBLAS_OP_T;
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa));
    cublasLtMatmulDescSetAttribute(matmul_desc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb));

    // Matrix layouts
    // A_cublas = B (col-major [N,K]), lda=N
    cublasLtMatrixLayout_t layout_B, layout_A, layout_C;
    cublasLtMatrixLayoutCreate(&layout_B, CUDA_R_32F, N, K, N); // B col-major [N,K]
    cublasLtMatrixLayoutCreate(&layout_A, CUDA_R_32F, M, K, M); // A col-major [M,K]
    cublasLtMatrixLayoutCreate(&layout_C, CUDA_R_32F, N, M, N); // C col-major [N,M]

    // Get heuristic algorithm
    cublasLtMatmulHeuristicResult_t heuristic;
    cublasLtMatmulPreference_t preference;
    cublasLtMatmulPreferenceCreate(&preference);
    cublasLtMatmulPreferenceSetAttribute(preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
